'use client';

import {
  checkboxesFeature,
  hotkeysCoreFeature,
  selectionFeature,
  syncDataLoaderFeature,
} from '@headless-tree/core';

import { WordRoll } from '@/components/core/word-roll';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { Tree, TreeItemLabel, useTree } from '@/registry/ndeko/ui/tree';

import { ItemCheckbox } from './_parts/item-checkbox';
import {
  branchLoaderOf,
  countIn,
  hasChildren,
  indexBranches,
  leafIdsOf,
  nameOf,
  type Branch,
} from './_parts/tree-data';
import { TreeRow, TreeRows } from './_parts/tree-rows';

const NOTIFICATIONS: Branch = {
  id: 'notifications',
  name: 'Harbor push notifications',
  children: [
    {
      id: 'projects',
      name: 'Projects',
      children: [
        {
          id: 'tasks',
          name: 'Tasks',
          children: [
            { id: 'assigned-to-me', name: 'Assigned to me' },
            { id: 'due-tomorrow', name: 'Due tomorrow' },
            { id: 'marked-done', name: 'Marked done' },
          ],
        },
        { id: 'mentions', name: 'Comments and mentions' },
        { id: 'weekly-summary', name: 'Weekly summary' },
      ],
    },
    {
      id: 'billing',
      name: 'Billing',
      children: [
        { id: 'invoice-ready', name: 'Invoice ready' },
        { id: 'payment-failed', name: 'Payment failed' },
      ],
    },
    {
      id: 'security',
      name: 'Security',
      children: [
        { id: 'new-sign-in', name: 'New sign-in' },
        { id: 'password-changed', name: 'Password changed' },
      ],
    },
  ],
};

const TOPICS = indexBranches(NOTIFICATIONS);

const TOPIC_LOADER = branchLoaderOf(TOPICS);

const ALERT_IDS = leafIdsOf(TOPICS);

const OPEN_AT_START = ['projects', 'tasks'];

const ON_AT_START = [
  'assigned-to-me',
  'due-tomorrow',
  'payment-failed',
  'new-sign-in',
];

export default function Tree13() {
  const tree = useTree<Branch>({
    initialState: {
      expandedItems: OPEN_AT_START,
      checkedItems: ON_AT_START,
    },
    rootItemId: NOTIFICATIONS.id,
    getItemName: nameOf,
    isItemFolder: hasChildren,
    dataLoader: TOPIC_LOADER,
    features: [
      syncDataLoaderFeature,
      hotkeysCoreFeature,
      selectionFeature,
      checkboxesFeature,
    ],
  });
  const { checkedItems } = tree.getState();
  const onCount = countIn(ALERT_IDS, checkedItems);
  const summary = `${onCount} of ${ALERT_IDS.length} on`;

  return (
    <div className='relative flex w-full flex-col gap-2'>
      <div className='flex items-baseline justify-between gap-2'>
        <h3 className='truncate text-[13px] font-medium'>Push notifications</h3>
        <WordRoll
          text={summary}
          value={onCount}
          className='text-muted-foreground text-xs tabular-nums'
        />
      </div>
      <Tree aria-label={NOTIFICATIONS.name} tree={tree}>
        <TreeRows>
          {tree.getItems().map((item) => (
            <TreeRow
              key={item.getId()}
              item={item}
              trailing={<ItemCheckbox item={item} />}
            >
              <TreeItemLabel />
            </TreeRow>
          ))}
        </TreeRows>
      </Tree>
      <LiveRegion message={`Push notifications: ${summary}`} />
    </div>
  );
}

'use client';

import { CheckedState, type ItemInstance } from '@headless-tree/core';

import { Checkbox } from '@/registry/ndeko/ui/checkbox';

type ItemCheckboxProps<T> = {
  item: ItemInstance<T>;
};

/* The bottom margin matches the gap under each row, so the box sits on the middle of the label. */
export function ItemCheckbox<T>({ item }: ItemCheckboxProps<T>) {
  const state = item.getCheckedState();
  const isChecked = state === CheckedState.Checked;
  const isPartlyChecked = state === CheckedState.Indeterminate;

  function toggle() {
    void item.toggleCheckedState();
  }

  return (
    <Checkbox
      checked={isChecked}
      indeterminate={isPartlyChecked}
      onCheckedChange={toggle}
      aria-label={item.getItemName()}
      className='mb-0.5'
    />
  );
}

import {
  isOrderedDragTarget,
  type DragTarget,
  type ItemInstance,
} from '@headless-tree/core';

export type Branch = {
  id: string;
  name: string;
  children?: Branch[];
};

type BranchIndex = Record<string, Branch>;

export type FlatNode = {
  name: string;
  isFolder: boolean;
  childIds: string[];
};

export type FlatNodes = Record<string, FlatNode>;

function idOf(branch: Branch) {
  return branch.id;
}

function childIdsOf(branch: Branch) {
  const children = branch.children ?? [];
  return children.map(idOf);
}

function collectBranches(branch: Branch, index: BranchIndex) {
  index[branch.id] = branch;
  const children = branch.children ?? [];
  children.forEach((child) => collectBranches(child, index));
}

export function indexBranches(root: Branch) {
  const index: BranchIndex = {};
  collectBranches(root, index);
  return index;
}

export function branchLoaderOf(index: BranchIndex) {
  function getItem(branchId: string) {
    return index[branchId];
  }

  function getChildren(branchId: string) {
    const branch = index[branchId];
    return childIdsOf(branch);
  }

  return { getItem, getChildren };
}

export function nameOf<Data extends { name: string }>(
  item: ItemInstance<Data>
) {
  return item.getItemData().name;
}

export function hasChildren(item: ItemInstance<Branch>) {
  const children = item.getItemData().children ?? [];
  return children.length > 0;
}

export function leafIdsOf(index: BranchIndex) {
  const branches = Object.values(index);
  const leaves = branches.filter((branch) => branch.children === undefined);
  return leaves.map(idOf);
}

export function folderIdsOf(index: BranchIndex) {
  const branches = Object.values(index);
  const folders = branches.filter((branch) => branch.children !== undefined);
  return folders.map(idOf);
}

/* A tree may list a checked id twice, so the ids are counted from the side that has each of them once. */
export function countIn(ids: string[], pickedIds: string[]) {
  const picked = ids.filter((id) => pickedIds.includes(id));
  return picked.length;
}

export function parentIdsOf(index: BranchIndex) {
  const parentIds: Record<string, string> = {};
  for (const branch of Object.values(index)) {
    for (const childId of childIdsOf(branch)) {
      parentIds[childId] = branch.id;
    }
  }
  return parentIds;
}

function flatNodeOf(branch: Branch): FlatNode {
  const isFolder = branch.children !== undefined;
  const childIds = childIdsOf(branch);
  return { name: branch.name, isFolder, childIds };
}

export function flattenBranches(root: Branch) {
  const index = indexBranches(root);
  const nodes: FlatNodes = {};
  for (const [branchId, branch] of Object.entries(index)) {
    nodes[branchId] = flatNodeOf(branch);
  }
  return nodes;
}

export function isFlatFolder(item: ItemInstance<FlatNode>) {
  return item.getItemData().isFolder;
}

function withoutIds(ids: string[], removedIds: string[]) {
  return ids.filter((id) => !removedIds.includes(id));
}

function insertedAt(ids: string[], index: number, addedIds: string[]) {
  const before = ids.slice(0, index);
  const after = ids.slice(index);
  return [...before, ...addedIds, ...after];
}

function slotOf(target: DragTarget<FlatNode>, siblingCount: number) {
  if (isOrderedDragTarget(target)) {
    return target.insertionIndex;
  }
  return siblingCount;
}

/** One update for the whole drop, so no render ever shows the moved rows missing from the tree. */
export function moveNodes(
  nodes: FlatNodes,
  movedIds: string[],
  target: DragTarget<FlatNode>
) {
  const moved: FlatNodes = {};
  for (const [nodeId, node] of Object.entries(nodes)) {
    const childIds = withoutIds(node.childIds, movedIds);
    moved[nodeId] = { ...node, childIds };
  }
  const parentId = target.item.getId();
  const parent = moved[parentId];
  const slot = slotOf(target, parent.childIds.length);
  const childIds = insertedAt(parent.childIds, slot, movedIds);
  moved[parentId] = { ...parent, childIds };
  return moved;
}

'use client';

import type { useRender } from '@base-ui/react/use-render';
import type { ItemInstance } from '@headless-tree/core';
import { AnimatePresence, motion, useIsPresent } from 'motion/react';
import { createContext, useContext, useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  EASE_IN_OUT_STRONG,
  rowPresenceOf,
  springOf,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { TreeItem } from '@/registry/ndeko/ui/tree';

/*
 * The highlight is one element shared by every row of a tree. It glides to the row that mounts it
 * only when that row gives it another layout dependency than the row it left, hence the row id.
 */
const HighlightContext = createContext<string | undefined>(undefined);

const TRAVEL = { duration: 0.25, ease: EASE_IN_OUT_STRONG };

const NO_TRAVEL = { duration: 0 };

const FRAME = 'flex min-w-0 items-center gap-1.5';

const ITEM = 'relative min-w-0 flex-1 ps-(--row-indent) pb-0.5';

const HIGHLIGHT =
  'bg-primary/[0.08] pointer-events-none absolute start-(--row-indent) end-0 top-0 bottom-0.5 -z-10 rounded-md';

/* The highlight glides between rows, so the label stops drawing its own tint on a selected row. A search match keeps its colour. */
const LABEL_WITHOUT_TINT =
  '[&[data-selected=true]:not([data-search-match=true])_[data-slot=tree-item-label]]:bg-transparent';

/* One hairline per level of nesting, each under the icon of the folder it belongs to. */
const GUIDES = [
  'bg-no-repeat [background-position:-0.25rem_0] [background-size:var(--row-indent)_100%]',
  'bg-[repeating-linear-gradient(to_right,transparent_0_calc(var(--tree-indent)_-_var(--hairline)),var(--border)_calc(var(--tree-indent)_-_var(--hairline))_var(--tree-indent))]',
].join(' ');

function travelOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return NO_TRAVEL;
  }
  return TRAVEL;
}

function layoutOf(travels: boolean) {
  if (travels) {
    return 'position' as const;
  }
  return false;
}

/* A tree set up without the selection feature keeps no list of selected rows. */
function selectedIdsOf<T>(item: ItemInstance<T>) {
  const { selectedItems } = item.getTree().getState();
  return selectedItems ?? [];
}

/* A row that left the visible tree reports level -1 while it fades out: it keeps the indent it had. */
function useShownLevel<T>(item: ItemInstance<T>) {
  const { level } = item.getItemMeta();
  const [shownLevel, setShownLevel] = useState(level);
  const isInTree = level >= 0;
  const hasMoved = level !== shownLevel;
  if (isInTree && hasMoved) {
    setShownLevel(level);
    return level;
  }
  return shownLevel;
}

type TreeRowsProps = {
  children: React.ReactNode;
};

/* Rows that are there when the tree mounts do not animate: only the ones a folder opens or closes later do. */
export function TreeRows({ children }: TreeRowsProps) {
  const highlightId = useId();

  return (
    <HighlightContext.Provider value={highlightId}>
      <AnimatePresence initial={false}>{children}</AnimatePresence>
    </HighlightContext.Provider>
  );
}

type TreeRowProps<T> = {
  item: ItemInstance<T>;
  children: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  render?: useRender.ComponentProps<'button'>['render'];
  hasGuides?: boolean;
  travels?: boolean;
  className?: string;
};

export function TreeRow<T>({
  item,
  children,
  leading,
  trailing,
  render,
  hasGuides = false,
  travels = false,
  className,
}: TreeRowProps<T>) {
  const highlightId = useContext(HighlightContext);
  const shouldReduceMotion = usePrefersReducedMotion();
  const isPresent = useIsPresent();
  const [isResizing, setIsResizing] = useState(false);
  const level = useShownLevel(item);
  const presence = rowPresenceOf(shouldReduceMotion);
  const travel = travelOf(shouldReduceMotion);
  const transition = { ...presence.transition, layout: travel };
  const glide = springOf(shouldReduceMotion);
  const layout = layoutOf(travels);
  const itemId = item.getId();
  const position = item.getItemMeta().index;
  const selectedIds = selectedIdsOf(item);
  const isSelected = selectedIds.includes(itemId);
  const isOnlySelected = isSelected && selectedIds.length === 1;
  /* A row on its way out keeps a plain tint, so its removal never waits for the highlight to land elsewhere. */
  const hasGlidingTint = isOnlySelected && isPresent;
  const hasStillTint = isSelected && !hasGlidingTint;
  const isClipped = isResizing || !isPresent;
  const frameStyle = {
    '--row-indent': `calc(var(--tree-indent) * ${level})`,
  } as React.CSSProperties;

  function startResizing() {
    setIsResizing(true);
  }

  function stopResizing() {
    setIsResizing(false);
  }

  return (
    <motion.div
      data-slot='tree-row'
      style={frameStyle}
      className={cn(FRAME, isClipped && 'overflow-hidden')}
      layout={layout}
      layoutDependency={position}
      onAnimationStart={startResizing}
      onAnimationComplete={stopResizing}
      {...presence}
      transition={transition}
    >
      {leading}
      <TreeItem
        item={item}
        render={render}
        className={cn(ITEM, LABEL_WITHOUT_TINT, hasGuides && GUIDES, className)}
      >
        {hasGlidingTint && (
          <motion.span
            layoutId={highlightId}
            layoutDependency={itemId}
            transition={glide}
            aria-hidden='true'
            className={HIGHLIGHT}
          />
        )}
        {hasStillTint && <span aria-hidden='true' className={HIGHLIGHT} />}
        {children}
      </TreeItem>
      {trailing}
    </motion.div>
  );
}
